'use strict';

/**
* Construct a Givens plane rotation.
*
* @module @stdlib/blas/base/zrotg
*
* @example
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var zrotg = require( '@stdlib/blas/base/zrotg' );
*
* var za = new Complex128( 5.0, 6.0 );
* // returns <Complex128>
*
* var zb = new Complex128( 0.0, 0.0 );
* // returns <Complex128>
*
* var out = zrotg( za, zb );
* // returns <Float64Array>[ 5.0, 6.0, 1.0, 0.0, 0.0 ]
*
* za = new Complex128( 3.0, 4.0 );
* // returns <Complex128>
*
* zb = new Complex128( 5.0, 12.0 );
* // returns <Complex128>
*
* out = zrotg( za, zb );
* // out => <Float64Array>[ 8.357032966310472,11.142710621747296,0.358979079308869,0.9046272798583499,-0.22974661075767622 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var zrotg;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	zrotg = main;
} else {
	zrotg = tmp;
}


// EXPORTS //

module.exports = zrotg;

// exports: { "assign": "zrotg.assign" }
